#!/usr/bin/env bash
# Writes Formula/ibis.rb for one Ibis release, from the checksums that release publishes.
# Usage: update-formula.sh [vX.Y.Z]   (default: the newest stable release)
set -euo pipefail

repo="ibiscite/ibis"
api() {
  curl -fsSL --retry 3 ${GITHUB_TOKEN:+-H "Authorization: Bearer ${GITHUB_TOKEN}"} \
    -H "Accept: application/vnd.github+json" "https://api.github.com/repos/${repo}/$1"
}

tag="${1:-$(api releases/latest | jq -r .tag_name)}"
if [[ ! "${tag}" =~ ^v([0-9]+\.[0-9]+\.[0-9]+)$ ]]; then
  echo "not a stable release tag: ${tag}" >&2
  exit 1
fi
version="${BASH_REMATCH[1]}"
base="https://github.com/${repo}/releases/download/${tag}"

# The checksum of one archive, read from the list published beside it.
sum() {
  local value
  value="$(curl -fsSL --retry 3 "${base}/SHA256SUMS-$1.txt" | awk -v name="$2" '$2 == name { print $1 }')"
  if [[ ! "${value}" =~ ^[0-9a-f]{64}$ ]]; then
    echo "no checksum for $2 in ${tag}" >&2
    exit 1
  fi
  printf '%s' "${value}"
}

arm="$(sum aarch64-apple-darwin ibis-macOS-Apple-silicon.tar.gz)"
intel="$(sum x86_64-apple-darwin ibis-macOS-Intel.tar.gz)"
linux="$(sum x86_64-unknown-linux-gnu ibis-Linux.tar.gz)"

cat > "$(dirname "$0")/../../Formula/ibis.rb" <<FORMULA
# Generated by .github/scripts/update-formula.sh; edit that script, not this file.
class Ibis < Formula
  desc "Search your reference library and cite from a terminal or an AI agent"
  homepage "https://ibiscite.org"
  license "AGPL-3.0-or-later"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "${base}/ibis-macOS-Apple-silicon.tar.gz"
      sha256 "${arm}"
    end
    on_intel do
      url "${base}/ibis-macOS-Intel.tar.gz"
      sha256 "${intel}"
    end
  end

  on_linux do
    on_intel do
      url "${base}/ibis-Linux.tar.gz"
      sha256 "${linux}"
    end
  end

  def install
    bin.install "ibis"
    doc.install "NOTICE.md"
    generate_completions_from_executable(bin/"ibis", "completions")
  end

  test do
    (testpath/"refs.bib").write <<~BIB
      @book{lee2024,
        title = {An Invented Field Guide},
        author = {Lee, Ada},
        year = {2024}
      }
    BIB
    assert_match version.to_s, shell_output("#{bin}/ibis --version")
    assert_equal "(Lee, 2024)",
                 shell_output("#{bin}/ibis cite lee2024 --file #{testpath}/refs.bib --style apa").strip
  end
end
FORMULA
echo "Formula/ibis.rb is Ibis ${version}"
